function support(){const T=[["Buying Help",[["How do I buy something?","Open Products, find an item, message the seller to confirm availability, colour and price, and add it to your cart. Checkout and payment arrive in the next phase."],["Can I negotiate the price?","Only when the listing says Negotiable. Use Messages to agree a price with the seller."]]],["Selling Help",[["How do I start selling?","Create an account, tap Start Selling and complete the short seller setup. You don't need a physical shop; choose a home, school, office or other pickup location."],["Is my pickup address public?","No. Only your business name, public city or area and verification statuses are shown. Pickup address and phone stay private."]]],["Finding Services Help",[["How do I find a provider?","Open Services, search or choose a category, then tap Request Service on a listing. Your request goes to the provider as a message; they can inspect the job and give a price."],["What does Price on contact mean?","The provider can't know the final price until they understand or inspect the job."]]],["Payment Help",[["How do I pay?","Online payments are not available yet. Don't pay in advance to anyone you haven't verified. Protected payments are planned."]]],["Delivery Help",[["How does delivery work?","Each listing shows pickup or seller delivery. Automated delivery quotes and tracking are planned."]]],["Account Help",[["What does 'not verified' mean?","Identity, address and shop location are verified separately. Mavora never marks an account verified unless the check was completed. Verification tools are coming."],["I forgot my password.","On the sign-in screen tap Forgot password, or open Account, then Password / Security."]]]];
$("app").innerHTML=`<h1 style="margin-top:22px">Help &amp; Support</h1>${T.map(t=>`<div class="pan" style="padding:6px 14px"><h3 class="lt">${t[0]}</h3>${t[1].map(x=>`<details style="padding:10px 0;border-top:1px solid var(--bd)"><summary style="cursor:pointer;font-weight:600">${x[0]}</summary><p class="mu">${x[1]}</p></details>`).join("")}</div>`).join("")}<div class="pan"><h3>Report a problem / Contact support</h3>${SUPPORT?`<p class="mu">Describe the problem, include the listing or seller name, and we'll look into it.</p><a class="btn pr" href="mailto:${esc(SUPPORT)}?subject=Mavora%20problem%20report">Email ${esc(SUPPORT)}</a>`:'<p class="mu">Support email not configured yet. Add <code>export const supportEmail = "you@example.com";</code> to firebase-config.js. In-app reporting is coming soon.</p>'}</div>`}
