async function up(file){if(!CLD)throw new Error("nocld");if(!file.type.startsWith("image/")||file.size>5e6)throw new Error("big");const f=new FormData();f.append("file",file);f.append("upload_preset",CLD.uploadPreset);const r=await fetch(`https://api.cloudinary.com/v1_1/${CLD.cloudName}/image/upload`,{method:"POST",body:f});if(!r.ok)throw new Error("up");return(await r.json()).secure_url}
