$("app").innerHTML=`<h1 style="margin-top:22px">Become a seller</h1><form class="pan" id="sl"><div class="fg"><div><label>Business or display name</label><input name="bn" required minlength="2" maxlength="80"></div><div><label>City / area (public)</label><input name="lo" required maxlength="80" placeholder="Yaba, Lagos"></div><div><label>Contact phone (private)</label><input name="ph" type="tel" required pattern="[0-9+ ]{10,20}"></div></div><label>About you or your business</label><textarea name="ds" rows="2" maxlength="400"></textarea><div class="fg"><div><label>I am an</label><select name="ptype"><option value="INDIVIDUAL">Individual</option><option value="BUSINESS">Business</option></select></div><div><label>Service area (optional)</label><input name="sa" maxlength="120" placeholder="e.g. Lekki, Ajah, Ikoyi"></div></div><label>Do you have a physical shop?</label><select name="hs" id="hs"><option value="no">No, I don't have a shop</option><option value="yes">Yes, I have a shop</option></select><div id="sx"></div><div id="tsw" style="margin-top:10px"></div><div class="err" id="er"></div><button class="pr" style="margin-top:14px">Create seller profile</button><p class="mu">Your pickup address and phone stay private. Verification is completed separately later.</p></form>`;
