const g=async c=>{try{return(await getDocs(query(collection(db,c),where("sellerId","==",U.uid)))).docs.map(d=>({id:d.id,...d.data()}))}catch(e){return[]}};const[p,v]=await Promise.all([g("products"),g("services")]);DM={};p.forEach(x=>DM["products"+x.id]=x);v.forEach(x=>DM["services"+x.id]=x);
