async function orderPage(id){if(gate())return;$("app").innerHTML='<div class="empty" style="margin-top:20px">Loading…</div>';let s;try{s=await getDoc(doc(db,"orders",id))}catch(e){}if(!s||!s.exists()){$("app").innerHTML='<div class="pan">Order not found.</div>';return}
const o={id,...s.data()},sell=o.sellerId===U.uid,nx=(sell?NEXT_S:NEXT_B)[o.status]||[],d=o.delivery||{};
$("app").innerHTML=`<p style="margin-top:18px"><a href="#/orders${sell?"?tab=sell":""}">← Orders</a></p><div class="pan"><div class="row" style="justify-content:space-between"><h1 style="font-size:22px">${esc(o.orderNumber)}</h1><span class="tag ${stCol(o.status)}">${esc(o.status)}</span></div><div class="mu">${fmt(o.createdAt?.toDate?.())} · ${sell?"Buyer: "+esc(o.buyerName):"Seller: "+esc(o.sellerName)}</div>${o.items.map(x=>`<div class="rw" style="flex-wrap:nowrap"><div class="rt"><b>${esc(x.name)}</b><div class="mu">${x.color?esc(x.color)+" · ":""}${money(x.price)} × ${x.qty}</div></div><b>${money(x.price*x.qty)}</b></div>`).join("")}<div class="row" style="justify-content:space-between;padding-top:12px"><b>Total</b><b>${money(o.total)}</b></div><div class="mu">${esc(o.payment||"")}</div></div><div class="pan"><h3>Delivery details</h3><div>${esc(d.name)} · ${esc(d.phone)}</div><div>${esc(d.address)}, ${esc(d.city)}, ${esc(d.state)}</div>${d.notes?`<div class="mu">Note: ${esc(d.notes)}</div>`:""}</div><div class="pan"><h3>Progress</h3>${(o.history||[]).map(h=>`<div class="row" style="justify-content:space-between"><span>${esc(h.status)}</span><span class="mu">${fmt(h.at?.toDate?.())}</span></div>`).join("")}</div><div class="pan"><div class="row" id="oa">${nx.map(t=>`<button class="${t==="Cancelled"?"":"pr"}" data-st="${esc(t)}">${t==="Cancelled"?(o.status==="Pending"&&sell?"Reject order":"Cancel order"):OLBL[t]||t}</button>`).join("")}<button id="om">Message ${sell?"buyer":"seller"}</button></div></div>`;
$("oa").querySelectorAll("[data-st]").forEach(b=>b.onclick=async()=>{const t=b.dataset.st;if(t==="Cancelled"&&!confirm("Cancel this order? The stock will be returned."))return;b.disabled=true;try{await api("/api/orders/"+encodeURIComponent(id)+"/status",{method:"PATCH",body:{status:t}});CACHE=null;toast("Order updated");orderPage(id)}catch(e){b.disabled=false;toast(e.message==="noapi"?"Server not connected yet":e.message)}});
$("om").onclick=()=>startChat(sell?o.buyerId:o.sellerId,sell?o.buyerName:o.sellerName,"seller","seller","",`Hi, about order ${o.orderNumber}: `)}
async function shop(slug){$("app").innerHTML='<div class="empty" style="margin-top:20px">Loading…</div>';let s;try{s=await getDoc(doc(db,"shopSlugs",String(slug||"").toLowerCase().slice(0,30)))}catch(e){}if(!s||!s.exists()){$("app").innerHTML='<div class="pan" style="margin-top:18px">Shop not found.</div>';return}seller(s.data().uid)}
function route(){unsub();const h=location.hash.slice(2).split("?")[0].split("/"),m={account:"au",sell:"au",dashboard:"au",settings:"au",messages:"nm",chat:"nm",support:"ns",cart:"nc",checkout:"nc",orders:"au",order:"au"},hm=["products","services","categories","service-categories","search","item","seller","shop"];MODE=h[0]==="products"?"products":h[0]==="services"?"services":"all";$("sf").q.placeholder=MODE==="products"?"Search products, shops or sellers":MODE==="services"?"Search services or service providers":"Search products, services, shops or sellers";NV.forEach(([i])=>$(i).classList.remove("on"));const a=h[0]===""?"nh":m[h[0]]||(hm.includes(h[0])?"nh":"");if(a)$(a).classList.add("on");({account:()=>account(),sell,dashboard:()=>dashboard().then(()=>{const ad=new URLSearchParams(location.hash.split("?")[1]||"").get("add");if(SP&&(ad==="products"||ad==="services"))lform(ad)}),search,support,settings,messages,chat:()=>chat(h[1]),item:()=>item(h[1],h[2]),seller:()=>seller(h[1]),products,services,categories,"service-categories":serviceCats,cart:cartPage,checkout,orders,order:()=>orderPage(h[1]),shop:()=>shop(h[1])}[h[0]]||home)();scrollTo(0,0);cartBadge()}
addEventListener("hashchange",route);theme();if(standalone)document.documentElement.classList.add("pwa");
if("serviceWorker"in navigator)addEventListener("load",()=>navigator.serviceWorker.register("sw.js"));
